  const w2y = Math.cos(y*0.011-t*0.12)*25 + Math.sin(x*0.008-t*0.18)*20;
  const sx = x + w1x + w2x*0.5, sy = y + w1y + w2y*0.5;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*55, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 220+Math.sin(t*0.75+4)*45, 0.13, 1.8, 1.05]
  ];
  let aS=0, iS=0, cross=0;
  for (let i=0; i<src.length; i++) {
    const [sX,sY,f,sp,w] = src[i];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp)*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    for (let j=i+1; j<src.length; j++) {
      const [sX2,sY2,f2,sp2,w2] = src[j];
      const d2 = Math.sqrt((sx-sX2)**2 + (sy-sY2)**2);
      cross += Math.sin((d*f+d2*f2)*0.5 - t*(sp+sp2)*0.5)*w*w2*0.15;
    }
  }
  const tw = src.reduce((a,s)=>a+s[4],0);
  const act = aS/tw, inh = iS/tw, crx = cross/tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
