  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + crx*0.8 + micro)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const edge = 1.0 - Math.pow(Math.abs(reaction), 12)*0.6;
  const glow = Math.pow(Math.max(0, Math.abs(reaction)-0.6)/0.4, 2)*0.3;
  const blend = reaction*0.65 + cell*0.2 + glow*0.15, v = blend*0.5+0.5;
