    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*e)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*e)|0
  ];
}
